import{_ as e,o as a,c as i,ag as o}from"./chunks/framework.Dk8PTAaz.js";const u=JSON.parse('{"title":"Platform Compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/compatibility.md","filePath":"en/guide/compatibility.md","lastUpdated":1788514798000}'),r={name:"en/guide/compatibility.md"};function d(n,t,l,s,c,p){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="platform-compatibility" tabindex="-1">Platform Compatibility <a class="header-anchor" href="#platform-compatibility" aria-label="Permalink to &quot;Platform Compatibility&quot;">​</a></h1><p>unix-router is written in <strong>UTS</strong> (<code>.uts</code>) and is compiled on the fly for each platform by the uni-app x build chain.</p><h2 id="compiled-output" tabindex="-1">Compiled Output <a class="header-anchor" href="#compiled-output" aria-label="Permalink to &quot;Compiled Output&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Platform</th><th>Compiled to</th><th>Supported</th></tr></thead><tbody><tr><td>Web / H5</td><td>JavaScript</td><td>✅</td></tr><tr><td>WeChat Mini Program</td><td>JavaScript</td><td>✅</td></tr><tr><td>Android (VDOM / vapor mode)</td><td>Kotlin / JS</td><td>✅</td></tr><tr><td>iOS (VDOM)</td><td>Swift / JS</td><td>✅</td></tr><tr><td>App-Android (VDOM native)</td><td>Kotlin</td><td>✅ (via UTS compilation)</td></tr></tbody></table><blockquote><p>Per the official rules: when the target language is JS, ts/js can be referenced directly; when it is not JS (Android), only ts files can be referenced, treated as UTS. This library is therefore distributed as <code>.uts</code> source, ensuring it compiles on all endpoints.</p></blockquote><h2 id="navigation-api-platform-differences" tabindex="-1">Navigation API Platform Differences <a class="header-anchor" href="#navigation-api-platform-differences" aria-label="Permalink to &quot;Navigation API Platform Differences&quot;">​</a></h2><p>Under the hood, it only depends on <code>uni.navigateTo / redirectTo / reLaunch / navigateBack / switchTab</code>, which are equalized across platforms by uni-app x&#39;s native adaptation layer.</p><ul><li><code>switchTab</code> (tabBar pages): consistent across endpoints.</li><li>App back key / swipe-back: does not pass through the router; it is synced by <code>syncRoute()</code> on <code>onShow</code>.</li></ul><h2 id="runtime-modes" tabindex="-1">Runtime Modes <a class="header-anchor" href="#runtime-modes" aria-label="Permalink to &quot;Runtime Modes&quot;">​</a></h2><ul><li><strong>VDOM mode</strong> (first generation): scripts compile to Kotlin/Swift and rely on strong UTS typing → this library is already adapted.</li><li><strong>Vapor mode</strong> (the new generation starting 2026): runs JS on all endpoints → this library runs here too.</li></ul><p>Both modes can be used directly without changing your code.</p><h2 id="how-to-verify" tabindex="-1">How to Verify <a class="header-anchor" href="#how-to-verify" aria-label="Permalink to &quot;How to Verify&quot;">​</a></h2><ul><li>Web / Mini Program: the <code>pages/test</code> self-check page in <code>packages/playground</code> outputs PASS/FAIL.</li><li>App native: open the playground in HBuilderX and package it to verify.</li></ul>',13)])])}const m=e(r,[["render",d]]);export{u as __pageData,m as default};
